'use client'

import { useState } from 'react'

interface UserInfo {
  id: string
  username: string
  displayName: string
  avatar: string
  bannerColor: string
  themeColor: string
  email?: string
  creationDate: string
  accountAge: string
  profileBackground: string
}

export default function DiscordLookup() {
  const [userId, setUserId] = useState('')
  const [userInfo, setUserInfo] = useState<UserInfo | null>(null)
  const [isLoading, setIsLoading] = useState(false)
  const [error, setError] = useState('')

  const handleSearch = async () => {
    if (!userId.trim()) {
      setError('Please enter a Discord User ID')
      return
    }

    setIsLoading(true)
    setError('')

    try {
      const response = await fetch('/api/lookup', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({ userId }),
      })

      const data = await response.json()

      if (!response.ok) {
        throw new Error(data.error || 'Failed to fetch user data')
      }

      setUserInfo(data)
    } catch (err) {
      setError(err instanceof Error ? err.message : 'An error occurred')
    } finally {
      setIsLoading(false)
    }
  }

  const handleKeyPress = (e: React.KeyboardEvent) => {
    if (e.key === 'Enter') {
      handleSearch()
    }
  }

  return (
    <div className="min-h-screen p-8" style={{backgroundColor: '#23272A'}}>
      <div className="max-w-6xl mx-auto">
        {/* Admin Header */}
        <div className="mb-8">
          <div className="flex items-center gap-4 mb-4">
            <div className="w-12 h-12 rounded-lg flex items-center justify-center" style={{backgroundColor: '#5865F2'}}>
              <svg className="w-8 h-8 text-white" fill="currentColor" viewBox="0 0 24 24">
                <path d="M20.317 4.37a19.791 19.791 0 0 0-4.885-1.515a.074.074 0 0 0-.079.037c-.21.375-.444.864-.608 1.25a18.27 18.27 0 0 0-5.487 0a12.64 12.64 0 0 0-.617-1.25a.077.077 0 0 0-.079-.037A19.736 19.736 0 0 0 3.677 4.37a.07.07 0 0 0-.032.027C.533 9.046-.32 13.58.099 18.057a.082.082 0 0 0 .031.057a19.9 19.9 0 0 0 5.993 3.03a.078.078 0 0 0 .084-.028a14.09 14.09 0 0 0 1.226-1.994a.076.076 0 0 0-.041-.106a13.107 13.107 0 0 1-1.872-.892a.077.077 0 0 1-.008-.128a10.2 10.2 0 0 0 .372-.292a.074.074 0 0 1 .077-.01c3.928 1.793 8.18 1.793 12.062 0a.074.074 0 0 1 .078.01c.12.098.246.198.373.292a.077.077 0 0 1-.006.127a12.299 12.299 0 0 1-1.873.892a.077.077 0 0 0-.041.107c.36.698.772 1.362 1.225 1.993a.076.076 0 0 0 .084.028a19.839 19.839 0 0 0 6.002-3.03a.077.077 0 0 0 .032-.054c.5-5.177-.838-9.674-3.549-13.66a.061.061 0 0 0-.031-.03zM8.02 15.33c-1.183 0-2.157-1.085-2.157-2.419c0-1.333.956-2.419 2.157-2.419c1.21 0 2.176 1.096 2.157 2.42c0 1.333-.956 2.418-2.157 2.418zm7.975 0c-1.183 0-2.157-1.085-2.157-2.419c0-1.333.955-2.419 2.157-2.419c1.21 0 2.176 1.096 2.157 2.42c0 1.333-.946 2.418-2.157 2.418z"/>
              </svg>
            </div>
            <div>
              <h1 className="text-3xl font-bold mb-1" style={{color: 'white'}}>Discord Database System</h1>
              <div className="flex items-center gap-2">
                <div className="w-2 h-2 rounded-full" style={{backgroundColor: '#43B581'}}></div>
                <span style={{color: '#99AAB5'}} className="text-sm">Admin Panel • User Management System</span>
              </div>
            </div>
          </div>
        </div>

        {/* Search Section */}
        <div className="discord-card mb-8">
          <div className="mb-6">
            <div className="flex items-center justify-between mb-4">
              <h2 className="text-xl font-semibold" style={{color: 'white'}}>User Database Query</h2>
              <div className="flex items-center gap-2">
                <div className="w-2 h-2 rounded-full animate-pulse" style={{backgroundColor: '#5865F2'}}></div>
                <span style={{color: '#99AAB5'}} className="text-sm">System Online</span>
              </div>
            </div>
            <p style={{color: '#99AAB5'}} className="text-sm mb-4">Enter Discord User ID to retrieve user profile data from the database</p>
          </div>
          
          <div className="flex gap-4">
            <div className="flex-1">
              <label style={{color: '#99AAB5'}} className="text-sm mb-2 block">User ID</label>
              <input
                type="text"
                value={userId}
                onChange={(e) => setUserId(e.target.value)}
                onKeyPress={handleKeyPress}
                placeholder="Enter Discord User ID (e.g., 1112367855728607262)..."
                className="discord-input w-full"
              />
            </div>
            <div className="flex items-end">
              <button
                onClick={handleSearch}
                disabled={isLoading}
                className="discord-button disabled:opacity-50 disabled:cursor-not-allowed"
              >
                {isLoading ? (
                  <div className="flex items-center gap-2">
                    <div className="w-4 h-4 border-2 border-white border-t-transparent rounded-full animate-spin"></div>
                    Querying...
                  </div>
                ) : (
                  <div className="flex items-center gap-2">
                    <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                      <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z" />
                    </svg>
                    Execute Query
                  </div>
                )}
              </button>
            </div>
          </div>
          {error && (
            <div className="mt-4 p-3 rounded-lg border" style={{backgroundColor: 'rgba(240, 71, 71, 0.1)', borderColor: '#F04747'}}>
              <div className="flex items-center gap-2">
                <svg className="w-5 h-5" style={{color: '#F04747'}} fill="currentColor" viewBox="0 0 20 20">
                  <path fillRule="evenodd" d="M10 18a8 8 0 100-16 8 8 0 000 16zM8.707 7.293a1 1 0 00-1.414 1.414L8.586 10l-1.293 1.293a1 1 0 101.414 1.414L10 11.414l1.293 1.293a1 1 0 001.414-1.414L11.414 10l1.293-1.293a1 1 0 00-1.414-1.414L10 8.586 8.707 7.293z" clipRule="evenodd" />
                </svg>
                <span style={{color: '#F04747'}} className="text-sm">{error}</span>
              </div>
            </div>
          )}
        </div>

        {/* User Info Display */}
        {userInfo && (
          <div className="space-y-6">
            {/* Profile Section */}
            <div className="discord-card">
              {/* Profile Background */}
              <div 
                className="h-48 rounded-t-lg -m-6 mb-4 relative overflow-hidden"
                style={{ backgroundColor: userInfo.bannerColor }}
              >
                <div className="absolute inset-0 bg-gradient-to-b from-transparent to-discord-darker/50"></div>
                <div className="absolute bottom-4 left-6 flex items-end">
                  <div className="w-24 h-24 rounded-full border-4 border-discord-darker overflow-hidden">
                    <img 
                      src={userInfo.avatar} 
                      alt={userInfo.displayName}
                      className="w-full h-full object-cover"
                      onError={(e) => {
                        const target = e.target as HTMLImageElement;
                        target.src = `https://api.dicebear.com/7.x/avataaars/svg?seed=${userInfo.id}`
                      }}
                    />
                  </div>
                  <div className="ml-4 mb-2">
                    <h2 className="text-2xl font-bold" style={{color: 'white'}}>{userInfo.displayName}</h2>
                    <p style={{color: '#99AAB5'}}>@{userInfo.username}</p>
                  </div>
                </div>
              </div>

              {/* User Details */}
              <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                <div>
                  <p style={{color: '#99AAB5'}} className="text-sm mb-1">Account Creation Date</p>
                  <p className="font-medium" style={{color: 'white'}}>{userInfo.creationDate}</p>
                </div>
                <div>
                  <p style={{color: '#99AAB5'}} className="text-sm mb-1">Account Age</p>
                  <p className="font-medium" style={{color: 'white'}}>{userInfo.accountAge}</p>
                </div>
                <div>
                  <p style={{color: '#99AAB5'}} className="text-sm mb-1">Banner Color</p>
                  <div className="flex items-center gap-2">
                    <div 
                      className="w-6 h-6 rounded border"
                      style={{ borderColor: 'rgba(153, 170, 181, 0.3)', backgroundColor: userInfo.bannerColor }}
                    ></div>
                    <p className="font-medium" style={{color: 'white'}}>{userInfo.bannerColor}</p>
                  </div>
                </div>
                <div>
                  <p style={{color: '#99AAB5'}} className="text-sm mb-1">Theme Color</p>
                  <div className="flex items-center gap-2">
                    <div 
                      className="w-6 h-6 rounded border"
                      style={{ borderColor: 'rgba(153, 170, 181, 0.3)', backgroundColor: userInfo.themeColor }}
                    ></div>
                    <p className="font-medium" style={{color: 'white'}}>{userInfo.themeColor}</p>
                  </div>
                </div>
                {userInfo.email && (
                  <div className="md:col-span-2">
                    <p style={{color: '#99AAB5'}} className="text-sm mb-1">Email Address</p>
                    <p className="font-medium" style={{color: 'white'}}>{userInfo.email}</p>
                  </div>
                )}
              </div>
            </div>

            {/* Account Standing Section */}
            <div className="discord-card" style={{borderLeft: '4px solid #F04747'}}>
              <div className="mb-4">
                <h3 className="text-xl font-bold mb-2" style={{color: 'white'}}>Account Standing</h3>
                <div className="flex items-center gap-2 mb-3">
                  <div className="w-3 h-3 rounded-full animate-pulse" style={{backgroundColor: '#F04747'}}></div>
                  <span style={{color: '#F04747'}} className="font-medium">Temporary Suspended</span>
                </div>
                <p style={{color: '#99AAB5', marginBottom: '1rem'}}>
                  Broke Discord's rules and will lose feature access if the user are unable to proceed with the Validation Process.
                </p>
              </div>

              <div className="mb-4">
                <p style={{color: '#99AAB5'}} className="text-sm mb-2">Active Violations: (3)</p>
                <div className="space-y-2">
                  <div className="flex items-center gap-2">
                    <span className="w-2 h-2 rounded-full" style={{backgroundColor: '#F04747'}}></span>
                    <span style={{color: 'white'}}>Impersonation</span>
                  </div>
                  <div className="flex items-center gap-2">
                    <span className="w-2 h-2 rounded-full" style={{backgroundColor: '#F04747'}}></span>
                    <span style={{color: 'white'}}>Child Endangerment</span>
                  </div>
                  <div className="flex items-center gap-2">
                    <span className="w-2 h-2 rounded-full" style={{backgroundColor: '#F04747'}}></span>
                    <span style={{color: 'white'}}>Financial Scam</span>
                  </div>
                </div>
              </div>

              <div>
                <p style={{color: '#99AAB5'}} className="text-sm mb-1">WalletAID:</p>
                <p className="font-mono text-sm" style={{color: 'white'}}>1PtMqhdbJAVYXXAY96EFjcHwVbusz1pmb</p>
              </div>
            </div>
          </div>
        )}
      </div>
    </div>
  )
}
